// Reads hex u32 bit patterns (one per line) from stdin, bitcasts to float,
// prints exactly what `std::ostream << std::fixed << std::setprecision(N) << f`
// produces for N = 1, 2, 3, tab separated.
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>

static std::string fmt(float f, int prec) {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(prec) << f;   // ostream<<float -> _M_insert<double>
    return oss.str();
}

int main() {
    std::ios::sync_with_stdio(false);
    char line[256];
    std::string out;
    out.reserve(1 << 20);
    while (std::fgets(line, sizeof line, stdin)) {
        if (line[0] == '\n' || line[0] == '\0') continue;
        uint32_t bits = (uint32_t)strtoul(line, nullptr, 16);
        float f;
        std::memcpy(&f, &bits, 4);
        char hb[16];
        std::snprintf(hb, sizeof hb, "%08x", bits);
        out += hb;
        out += '\t';
        out += fmt(f, 1);
        out += '\t';
        out += fmt(f, 2);
        out += '\t';
        out += fmt(f, 3);
        out += '\n';
        if (out.size() > (1u << 19)) { std::cout << out; out.clear(); }
    }
    std::cout << out;
    return 0;
}

// Reads hex u32 bit patterns (one per line) from stdin, bitcasts to f32,
// prints format!("{:.N$}", f) for N = 1, 2, 3, tab separated.
use std::io::{self, Read, Write};
use std::fmt::Write as _;

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut out = String::with_capacity(1 << 22);
    for line in s.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let bits = u32::from_str_radix(line, 16).unwrap();
        let f = f32::from_bits(bits);
        let _ = write!(
            out,
            "{:08x}\t{:.1}\t{:.2}\t{:.3}\n",
            bits, f, f, f
        );
    }
    io::stdout().write_all(out.as_bytes()).unwrap();
}

// Same as rs_fmt.rs but formats the f32 widened to f64 first.
// Used to answer: does Rust f32 fixed formatting == Rust (f32 as f64) fixed formatting?
use std::io::{self, Read, Write};
use std::fmt::Write as _;

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut out = String::with_capacity(1 << 22);
    for line in s.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let bits = u32::from_str_radix(line, 16).unwrap();
        let d = f32::from_bits(bits) as f64;
        let _ = write!(out, "{:08x}\t{:.1}\t{:.2}\t{:.3}\n", bits, d, d, d);
    }
    io::stdout().write_all(out.as_bytes()).unwrap();
}

// Emits hex u32 bit patterns (one per line) covering the sample space.
use std::collections::BTreeSet;
use std::io::{self, Write};

fn pct(c: i32) -> f32 {
    // exactly what the C++ does: (float)current * 100.0f / (float)total, total = 200
    (c as f32) * 100.0f32 / 200.0f32
}

fn main() {
    let which = std::env::args().nth(1).unwrap_or_else(|| "all".into());
    let mut set: BTreeSet<u32> = BTreeSet::new();
    let mut add = |set: &mut BTreeSet<u32>, f: f32| {
        set.insert(f.to_bits());
    };

    // ---- 1. reachable percentages ------------------------------------------
    if which == "all" || which == "pct" {
        // dense sweep of current
        let mut c: i64 = -3_000_000;
        while c <= 3_000_000 {
            add(&mut set, pct(c as i32));
            c += 1;
        }
        // powers of two +/- neighbourhood, both signs (covers i32 wraparound region)
        for k in 0..32u32 {
            let base: i64 = 1i64 << k;
            for d in -5000i64..=5000 {
                for s in [1i64, -1] {
                    let v = s * base + d;
                    if v >= i32::MIN as i64 && v <= i32::MAX as i64 {
                        add(&mut set, pct(v as i32));
                    }
                }
            }
        }
        // i32 extremes and wraparound results
        for v in [
            i32::MIN, i32::MIN + 1, i32::MIN + 25, i32::MAX, i32::MAX - 1,
            i32::MAX - 24, -2147483624, 2147483647, 0, 1, -1, 200, 201, -200,
        ] {
            add(&mut set, pct(v));
        }
        // pseudo-random current values over the whole i32 range
        let mut x: u64 = 0x2545F4914F6CDD1D;
        for _ in 0..4_000_000u32 {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            add(&mut set, pct(x as u32 as i32));
        }
    }

    // ---- 2. the literal Percentage cases and neighbours ---------------------
    if which == "all" || which == "pct" {
        for v in [0.15f32, 0.35, 0.65, 0.05, 0.25, 0.45, 0.55, 0.75, 0.85, 0.95, 1.0, 0.0] {
            add(&mut set, v * 100.0f32);
            add(&mut set, v);
        }
    }

    // ---- 3. exact decimal ties ---------------------------------------------
    if which == "all" || which == "ties" {
        // precision 1 ties: odd multiples of 1/4   (x.25 / x.75)
        // precision 2 ties: odd multiples of 1/8
        // precision 3 ties: odd multiples of 1/16
        for (den, n) in [(4i64, 400_000i64), (8, 400_000), (16, 400_000), (32, 200_000), (2, 400_000)] {
            for j in -n..=n {
                let m = 2 * j + 1; // odd numerator
                let v = m as f64 / den as f64;
                let f = v as f32;
                if (f as f64) == v {
                    add(&mut set, f);
                    add(&mut set, -f);
                }
            }
        }
        // k + 0.5 and k + 0.05 style
        for k in -20000i64..=20000 {
            for frac in [0.5f64, 0.05, 0.005, 0.0005, 0.25, 0.125, 0.375, 0.625, 0.875, 0.15, 0.35, 0.65, 0.45, 0.55] {
                add(&mut set, (k as f64 + frac) as f32);
                add(&mut set, (k as f64 - frac) as f32);
            }
        }
        // neighbours (1 ulp either side) of every tie collected so far
        let snapshot: Vec<u32> = set.iter().copied().collect();
        for b in snapshot {
            for d in [-3i64, -2, -1, 1, 2, 3] {
                let nb = (b as i64 + d) as u32;
                set.insert(nb);
            }
        }
    }

    // ---- 4. specials, subnormals, extremes ---------------------------------
    if which == "all" || which == "special" {
        for b in [
            0x0000_0000u32, // +0
            0x8000_0000,    // -0
            0x0000_0001,    // smallest positive subnormal
            0x8000_0001,
            0x0000_0002,
            0x007f_ffff,    // largest subnormal
            0x807f_ffff,
            0x0080_0000,    // smallest normal
            0x8080_0000,
            0x7f80_0000,    // +inf
            0xff80_0000,    // -inf
            0x7fc0_0000,    // +nan (quiet)
            0xffc0_0000,    // -nan (quiet)
            0x7f80_0001,    // +nan (signalling)
            0xff80_0001,    // -nan (signalling)
            0x7fbf_ffff,
            0xffbf_ffff,
            0x7f7f_ffff,    // f32::MAX
            0xff7f_ffff,    // f32::MIN
        ] {
            set.insert(b);
        }
        for v in [
            1e30f32, -1e30, 1e20, 1e-30, 1e-38, 1e-45, 3.4028235e38, 1e10, 1e15,
            16777216.0, 16777215.0, 8388608.0, 1e38, -1e38,
        ] {
            add(&mut set, v);
            add(&mut set, -v);
        }
        // whole subnormal range, strided
        let mut b = 1u32;
        while b < 0x0080_0000 {
            set.insert(b);
            set.insert(b | 0x8000_0000);
            b += 977;
        }
    }

    // ---- 5. global stride sweep of the entire f32 bit space -----------------
    if which == "all" || which == "sweep" {
        let stride: u64 = 2_477; // prime
        let mut b: u64 = 0;
        while b <= u32::MAX as u64 {
            set.insert(b as u32);
            b += stride;
        }
    }

    let stdout = io::stdout();
    let mut w = io::BufWriter::with_capacity(1 << 22, stdout.lock());
    let mut line = String::with_capacity(16);
    for b in set {
        line.clear();
        use std::fmt::Write as _;
        let _ = writeln!(line, "{:08x}", b);
        w.write_all(line.as_bytes()).unwrap();
    }
}

// Proves (or disproves) that libstdc++ `ostream << fixed << setprecision(N) << float`
// is byte-identical to glibc `snprintf(buf, n, "%.*f", N, (double)f)`.
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>

static std::string via_stream(float f, int prec) {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(prec) << f;
    return oss.str();
}
static std::string via_printf(float f, int prec) {
    char buf[512];
    std::snprintf(buf, sizeof buf, "%.*f", prec, (double)f);
    return std::string(buf);
}

int main() {
    std::ios::sync_with_stdio(false);
    char line[256];
    long long n = 0, bad = 0;
    while (std::fgets(line, sizeof line, stdin)) {
        if (line[0] == '\n' || line[0] == '\0') continue;
        uint32_t bits = (uint32_t)strtoul(line, nullptr, 16);
        float f; std::memcpy(&f, &bits, 4);
        for (int p = 1; p <= 3; ++p) {
            std::string a = via_stream(f, p), b = via_printf(f, p);
            if (a != b) {
                if (bad < 40)
                    std::printf("STREAM_VS_PRINTF_DIFF bits=%08x prec=%d stream=[%s] printf=[%s]\n",
                                bits, p, a.c_str(), b.c_str());
                ++bad;
            }
        }
        ++n;
    }
    std::printf("checked=%lld triples, mismatches=%lld\n", n, bad);
    return bad ? 1 : 0;
}

// Full differential: Rust `{:.N}` on f32  vs  glibc snprintf("%.*f", N, (double)f)
// (the latter proven byte-identical to libstdc++ `ostream << fixed << setprecision(N) << float`).
// Also checks Rust f32 formatting vs Rust (f32 as f64) formatting.
use std::os::raw::{c_char, c_double, c_int};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

extern "C" {
    fn snprintf(s: *mut c_char, n: usize, fmt: *const c_char, ...) -> c_int;
}

fn glibc_fixed(f: f32, prec: i32, buf: &mut [u8]) -> String {
    let fmt = b"%.*f\0";
    unsafe {
        let n = snprintf(
            buf.as_mut_ptr() as *mut c_char,
            buf.len(),
            fmt.as_ptr() as *const c_char,
            prec as c_int,
            f as c_double,
        );
        String::from_utf8_lossy(&buf[..n as usize]).into_owned()
    }
}

struct Report {
    // key: (class, prec) -> examples
    examples: Vec<(u32, i32, String, String, &'static str)>,
}

fn main() {
    let path = std::env::args().nth(1).expect("sample file");
    let data = std::fs::read(&path).expect("read sample");
    let nthreads = 32usize;
    let len = data.len();
    // split on line boundaries
    let mut bounds = vec![0usize];
    for t in 1..nthreads {
        let mut p = len * t / nthreads;
        while p < len && data[p] != b'\n' {
            p += 1;
        }
        if p < len {
            p += 1;
        }
        bounds.push(p.min(len));
    }
    bounds.push(len);

    let total = AtomicU64::new(0);
    let diff_glibc = AtomicU64::new(0);
    let diff_f64 = AtomicU64::new(0);
    let report = Mutex::new(Report { examples: Vec::new() });

    std::thread::scope(|sc| {
        for t in 0..nthreads {
            let (a, b) = (bounds[t], bounds[t + 1]);
            let data = &data;
            let total = &total;
            let diff_glibc = &diff_glibc;
            let diff_f64 = &diff_f64;
            let report = &report;
            sc.spawn(move || {
                let mut buf = [0u8; 512];
                let mut n_local = 0u64;
                let mut dg = 0u64;
                let mut df = 0u64;
                let mut local_ex: Vec<(u32, i32, String, String, &'static str)> = Vec::new();
                for line in data[a..b].split(|&c| c == b'\n') {
                    if line.is_empty() {
                        continue;
                    }
                    let s = std::str::from_utf8(line).unwrap().trim();
                    if s.is_empty() {
                        continue;
                    }
                    let bits = u32::from_str_radix(s, 16).unwrap();
                    let f = f32::from_bits(bits);
                    let d = f as f64;
                    for prec in 1..=3i32 {
                        let c = glibc_fixed(f, prec, &mut buf);
                        let r = match prec {
                            1 => format!("{:.1}", f),
                            2 => format!("{:.2}", f),
                            _ => format!("{:.3}", f),
                        };
                        let r64 = match prec {
                            1 => format!("{:.1}", d),
                            2 => format!("{:.2}", d),
                            _ => format!("{:.3}", d),
                        };
                        if c != r {
                            dg += 1;
                            if local_ex.len() < 60 {
                                local_ex.push((bits, prec, c.clone(), r.clone(), "glibc_vs_rust32"));
                            }
                        }
                        if r != r64 {
                            df += 1;
                            if local_ex.len() < 60 {
                                local_ex.push((bits, prec, r.clone(), r64.clone(), "rust32_vs_rust64"));
                            }
                        }
                    }
                    n_local += 1;
                }
                total.fetch_add(n_local, Ordering::Relaxed);
                diff_glibc.fetch_add(dg, Ordering::Relaxed);
                diff_f64.fetch_add(df, Ordering::Relaxed);
                report.lock().unwrap().examples.extend(local_ex);
            });
        }
    });

    println!("values checked      : {}", total.load(Ordering::Relaxed));
    println!("glibc != rust(f32)  : {}", diff_glibc.load(Ordering::Relaxed));
    println!("rust(f32)!=rust(f64): {}", diff_f64.load(Ordering::Relaxed));
    let r = report.lock().unwrap();
    let mut ex = r.examples.clone();
    ex.sort();
    ex.dedup();
    for (bits, prec, a, b, cls) in ex.iter().take(80) {
        println!(
            "  {} bits={:08x} val={:e} prec={} A=[{}] B=[{}]",
            cls,
            bits,
            f32::from_bits(*bits),
            prec,
            a,
            b
        );
    }
}

// Classify every Rust-vs-glibc fixed-format mismatch by value class.
// The only interesting answer is: are there ANY finite mismatches?
use std::os::raw::{c_char, c_double, c_int};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

extern "C" {
    fn snprintf(s: *mut c_char, n: usize, fmt: *const c_char, ...) -> c_int;
}

fn glibc_fixed(f: f32, prec: i32, buf: &mut [u8]) -> String {
    unsafe {
        let n = snprintf(
            buf.as_mut_ptr() as *mut c_char,
            buf.len(),
            b"%.*f\0".as_ptr() as *const c_char,
            prec as c_int,
            f as c_double,
        );
        String::from_utf8_lossy(&buf[..n as usize]).into_owned()
    }
}

fn main() {
    let path = std::env::args().nth(1).expect("sample file");
    let data = std::fs::read(&path).expect("read");
    let nthreads = 32usize;
    let len = data.len();
    let mut bounds = vec![0usize];
    for t in 1..nthreads {
        let mut p = len * t / nthreads;
        while p < len && data[p] != b'\n' { p += 1; }
        if p < len { p += 1; }
        bounds.push(p.min(len));
    }
    bounds.push(len);

    let total = AtomicU64::new(0);
    let m_nan = AtomicU64::new(0);
    let m_inf = AtomicU64::new(0);
    let m_finite = AtomicU64::new(0);
    let m_negzero = AtomicU64::new(0);
    let m_subnormal = AtomicU64::new(0);
    let finite_ex: Mutex<Vec<(u32, i32, String, String)>> = Mutex::new(Vec::new());
    let widths: Mutex<Vec<(usize, u32, String)>> = Mutex::new(Vec::new());

    std::thread::scope(|sc| {
        for t in 0..nthreads {
            let (a, b) = (bounds[t], bounds[t + 1]);
            let (data, total, m_nan, m_inf, m_finite, m_negzero, m_subnormal, finite_ex, widths) =
                (&data, &total, &m_nan, &m_inf, &m_finite, &m_negzero, &m_subnormal, &finite_ex, &widths);
            sc.spawn(move || {
                let mut buf = [0u8; 512];
                let (mut n, mut mn, mut mi, mut mf, mut mz, mut ms) = (0u64, 0u64, 0u64, 0u64, 0u64, 0u64);
                let mut fex = Vec::new();
                let mut wid: Vec<(usize, u32, String)> = Vec::new();
                for line in data[a..b].split(|&c| c == b'\n') {
                    let s = match std::str::from_utf8(line) { Ok(s) => s.trim(), Err(_) => continue };
                    if s.is_empty() { continue; }
                    let bits = u32::from_str_radix(s, 16).unwrap();
                    let f = f32::from_bits(bits);
                    for prec in 1..=3i32 {
                        let c = glibc_fixed(f, prec, &mut buf);
                        let r = match prec { 1 => format!("{:.1}", f), 2 => format!("{:.2}", f), _ => format!("{:.3}", f) };
                        // track the widest finite output seen (for the "huge value" question)
                        if f.is_finite() && c.len() >= 30 {
                            if wid.len() < 4 { wid.push((c.len(), bits, c.clone())); }
                        }
                        if c != r {
                            if f.is_nan() { mn += 1; }
                            else if f.is_infinite() { mi += 1; }
                            else {
                                mf += 1;
                                if f == 0.0 && f.is_sign_negative() { mz += 1; }
                                if f != 0.0 && f.abs() < f32::MIN_POSITIVE { ms += 1; }
                                if fex.len() < 50 { fex.push((bits, prec, c.clone(), r.clone())); }
                            }
                        }
                    }
                    n += 1;
                }
                total.fetch_add(n, Ordering::Relaxed);
                m_nan.fetch_add(mn, Ordering::Relaxed);
                m_inf.fetch_add(mi, Ordering::Relaxed);
                m_finite.fetch_add(mf, Ordering::Relaxed);
                m_negzero.fetch_add(mz, Ordering::Relaxed);
                m_subnormal.fetch_add(ms, Ordering::Relaxed);
                finite_ex.lock().unwrap().extend(fex);
                widths.lock().unwrap().extend(wid);
            });
        }
    });

    println!("values checked (x3 precisions) : {}", total.load(Ordering::Relaxed));
    println!("mismatches on NaN              : {}", m_nan.load(Ordering::Relaxed));
    println!("mismatches on +/-inf           : {}", m_inf.load(Ordering::Relaxed));
    println!("mismatches on FINITE values    : {}", m_finite.load(Ordering::Relaxed));
    println!("  ...of which -0.0             : {}", m_negzero.load(Ordering::Relaxed));
    println!("  ...of which subnormal        : {}", m_subnormal.load(Ordering::Relaxed));
    let fe = finite_ex.lock().unwrap();
    for (bits, prec, c, r) in fe.iter().take(50) {
        println!("  FINITE DIFF bits={:08x} prec={} glibc=[{}] rust=[{}]", bits, prec, c, r);
    }
    let mut w = widths.lock().unwrap().clone();
    w.sort_by_key(|x| std::cmp::Reverse(x.0));
    w.dedup();
    for (l, bits, s) in w.iter().take(3) {
        println!("  widest finite output len={} bits={:08x} [{}]", l, bits, s);
    }
}

// EXHAUSTIVE: every one of the 2^32 f32 bit patterns, at precisions 1, 2, 3.
// Compares Rust `{:.N}` against glibc snprintf("%.*f") == libstdc++ ostream<<fixed.
use std::os::raw::{c_char, c_double, c_int};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

extern "C" {
    fn snprintf(s: *mut c_char, n: usize, fmt: *const c_char, ...) -> c_int;
}

#[inline]
fn glibc_fixed<'a>(f: f32, prec: i32, buf: &'a mut [u8]) -> &'a str {
    unsafe {
        let n = snprintf(
            buf.as_mut_ptr() as *mut c_char,
            buf.len(),
            b"%.*f\0".as_ptr() as *const c_char,
            prec as c_int,
            f as c_double,
        );
        std::str::from_utf8_unchecked(&buf[..n as usize])
    }
}

fn main() {
    let nthreads: u64 = 64;
    let span: u64 = (1u64 << 32) / nthreads;

    let m_nan = AtomicU64::new(0);
    let m_inf = AtomicU64::new(0);
    let m_finite = AtomicU64::new(0);
    let m_f64 = AtomicU64::new(0);
    let done = AtomicU64::new(0);
    let ex: Mutex<Vec<String>> = Mutex::new(Vec::new());

    std::thread::scope(|sc| {
        for t in 0..nthreads {
            let lo = t * span;
            let hi = if t == nthreads - 1 { 1u64 << 32 } else { (t + 1) * span };
            let (m_nan, m_inf, m_finite, m_f64, done, ex) =
                (&m_nan, &m_inf, &m_finite, &m_f64, &done, &ex);
            sc.spawn(move || {
                let mut buf = [0u8; 512];
                let mut rs = String::with_capacity(512);
                let mut rs64 = String::with_capacity(512);
                let (mut mn, mut mi, mut mf, mut m6) = (0u64, 0u64, 0u64, 0u64);
                let mut local_ex: Vec<String> = Vec::new();
                for b in lo..hi {
                    let bits = b as u32;
                    let f = f32::from_bits(bits);
                    let d = f as f64;
                    for prec in 1..=3usize {
                        use std::fmt::Write;
                        rs.clear();
                        rs64.clear();
                        let _ = write!(rs, "{:.*}", prec, f);
                        let _ = write!(rs64, "{:.*}", prec, d);
                        if rs != rs64 {
                            m6 += 1;
                            if local_ex.len() < 20 {
                                local_ex.push(format!(
                                    "RUST32_VS_RUST64 bits={:08x} prec={} f32=[{}] f64=[{}]",
                                    bits, prec, rs, rs64
                                ));
                            }
                        }
                        let c = glibc_fixed(f, prec as i32, &mut buf);
                        if c != rs {
                            if f.is_nan() {
                                mn += 1;
                            } else if f.is_infinite() {
                                mi += 1;
                                if local_ex.len() < 20 {
                                    local_ex.push(format!(
                                        "INF_DIFF bits={:08x} prec={} glibc=[{}] rust=[{}]",
                                        bits, prec, c, rs
                                    ));
                                }
                            } else {
                                mf += 1;
                                if local_ex.len() < 20 {
                                    local_ex.push(format!(
                                        "FINITE_DIFF bits={:08x} prec={} glibc=[{}] rust=[{}]",
                                        bits, prec, c, rs
                                    ));
                                }
                            }
