                }
                m_nan.fetch_add(mn, Ordering::Relaxed);
                m_inf.fetch_add(mi, Ordering::Relaxed);
                m_finite.fetch_add(mf, Ordering::Relaxed);
                m_f64.fetch_add(m6, Ordering::Relaxed);
                done.fetch_add(hi - lo, Ordering::Relaxed);
                if !local_ex.is_empty() {
