// End-to-end: reimplement test7 in Rust and diff stdout against the reference binary
// for a wide range of argv[1] values. Validates the formatting decision in situ.
use std::process::Command;

fn pct_str(v: f32, prec: usize) -> String {
    format!("{:.*}", prec, v)
}

fn rust_program(progress: i32) -> String {
    let total: i32 = 200;
    let mut current: i32 = progress;
    let mut out = String::new();
    let p = (current as f32) * 100.0f32 / (total as f32);
    out.push_str(&format!("Progress: {}% ({}/{})\n", pct_str(p, 1), current, total));
    current = current.wrapping_add(25);
    let p = (current as f32) * 100.0f32 / (total as f32);
    out.push_str(&format!("Progress: {}% ({}/{})\n", pct_str(p, 1), current, total));
    out.push_str(&format!("{}%\n", pct_str(0.15f32 * 100.0f32, 1)));
    out.push_str(&format!("{}%\n", pct_str(0.35f32 * 100.0f32, 2)));
    out.push_str(&format!("{}%\n", pct_str(0.65f32 * 100.0f32, 3)));
    out
}

