// How often does the (wrong) multiply-first spec disagree with the (correct) divide-first
// one, over ALL 2^32 values of `current`? And where is the smallest disagreement?
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

#[inline] fn mul_first(c: i32) -> f32 { (c as f32) * 100.0f32 / 200.0f32 }
#[inline] fn div_first(c: i32) -> f32 { (c as f32) / 200.0f32 * 100.0f32 }

fn main() {
    let nt: u64 = 64;
    let span = (1u64 << 32) / nt;
    let diff_val = AtomicU64::new(0);
    let diff_str = AtomicU64::new(0);
    let smallest: Mutex<Vec<(u32, i32, String, String)>> = Mutex::new(Vec::new());

    std::thread::scope(|sc| {
        for t in 0..nt {
            let lo = t * span;
            let hi = if t == nt - 1 { 1u64 << 32 } else { (t + 1) * span };
            let (diff_val, diff_str, smallest) = (&diff_val, &diff_str, &smallest);
            sc.spawn(move || {
                let (mut dv, mut ds) = (0u64, 0u64);
                let mut best: Vec<(u32, i32, String, String)> = Vec::new();
                for u in lo..hi {
                    let c = u as u32 as i32;
                    let a = mul_first(c);
                    let b = div_first(c);
                    if a.to_bits() != b.to_bits() {
                        dv += 1;
                        let sa = format!("{:.1}", a);
                        let sb = format!("{:.1}", b);
                        if sa != sb {
                            ds += 1;
                            let mag = c.unsigned_abs();
                            if best.len() < 6 { best.push((mag, c, sa, sb)); }
                            else if let Some(m) = best.iter_mut().max_by_key(|x| x.0) {
                                if mag < m.0 { *m = (mag, c, sa, sb); }
                            }
                        }
                    }
                }
                diff_val.fetch_add(dv, Ordering::Relaxed);
                diff_str.fetch_add(ds, Ordering::Relaxed);
                smallest.lock().unwrap().extend(best);
            });
        }
    });
    let dv = diff_val.load(Ordering::Relaxed);
    let ds = diff_str.load(Ordering::Relaxed);
    println!("all 2^32 values of `current` = {}", 1u64 << 32);
    println!("mul-first != div-first (bitwise)   : {}  ({:.4}%)", dv, dv as f64 / 4294967296.0 * 100.0);
    println!("mul-first != div-first (rendered)  : {}  ({:.4}%)", ds, ds as f64 / 4294967296.0 * 100.0);
    let mut s = smallest.lock().unwrap().clone();
    s.sort();
    println!("smallest-|current| rendered disagreements:");
    for (_, c, a, b) in s.iter().take(8) {
        println!("   current={:<12} mul_first=[{}]  div_first=[{}]  <-- binary prints the div_first one", c, a, b);
    }
}

// Formatting equivalence across precisions 0..=20 (Percentage takes precision as a param).
use std::os::raw::{c_char, c_double, c_int};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;
extern "C" { fn snprintf(s: *mut c_char, n: usize, fmt: *const c_char, ...) -> c_int; }

fn g(f: f32, prec: i32, buf: &mut [u8]) -> String {
    unsafe {
        let n = snprintf(buf.as_mut_ptr() as *mut c_char, buf.len(),
            b"%.*f\0".as_ptr() as *const c_char, prec as c_int, f as c_double);
        String::from_utf8_lossy(&buf[..n as usize]).into_owned()
    }
}

fn main() {
    let data = std::fs::read("/tmp/fmtcmp/sample.txt").unwrap();
    let nt = 64usize; let len = data.len();
    let mut bounds = vec![0usize];
    for t in 1..nt { let mut p = len*t/nt; while p<len && data[p]!=b'\n' {p+=1;} if p<len {p+=1;} bounds.push(p.min(len)); }
    bounds.push(len);
    let fin = AtomicU64::new(0); let nan = AtomicU64::new(0); let inf = AtomicU64::new(0); let tot = AtomicU64::new(0);
    let ex: Mutex<Vec<String>> = Mutex::new(Vec::new());
    std::thread::scope(|sc| {
        for t in 0..nt {
            let (a,b)=(bounds[t],bounds[t+1]);
            let (data,fin,nan,inf,tot,ex)=(&data,&fin,&nan,&inf,&tot,&ex);
            sc.spawn(move || {
                let mut buf=[0u8;1024]; let (mut f_,mut n_,mut i_,mut c_)=(0u64,0u64,0u64,0u64);
                let mut lex=Vec::new();
                for line in data[a..b].split(|&c| c==b'\n') {
                    let s = match std::str::from_utf8(line){Ok(s)=>s.trim(),Err(_)=>continue};
                    if s.is_empty(){continue;}
                    let bits=u32::from_str_radix(s,16).unwrap(); let f=f32::from_bits(bits);
                    for prec in 0..=20i32 {
                        let cs=g(f,prec,&mut buf);
                        let rs=format!("{:.*}",prec as usize,f);
                        if cs!=rs {
                            if f.is_nan(){n_+=1;}
                            else if f.is_infinite(){i_+=1; if lex.len()<10 {lex.push(format!("INF prec={} bits={:08x} c=[{}] r=[{}]",prec,bits,cs,rs));}}
                            else {f_+=1; if lex.len()<10 {lex.push(format!("FINITE prec={} bits={:08x} c=[{}] r=[{}]",prec,bits,cs,rs));}}
                        }
                    }
                    c_+=1;
                }
                fin.fetch_add(f_,Ordering::Relaxed); nan.fetch_add(n_,Ordering::Relaxed);
                inf.fetch_add(i_,Ordering::Relaxed); tot.fetch_add(c_,Ordering::Relaxed);
                if !lex.is_empty(){ex.lock().unwrap().extend(lex);}
            });
        }
    });
    println!("values={} precisions=0..=20", tot.load(Ordering::Relaxed));
    println!("FINITE mismatches: {}", fin.load(Ordering::Relaxed));
    println!("INF    mismatches: {}", inf.load(Ordering::Relaxed));
    println!("NAN    mismatches: {}", nan.load(Ordering::Relaxed));
    for s in ex.lock().unwrap().iter().take(10) { println!("  {}", s); }
    // showcase prec 0 and high prec on the three literals
    let mut buf=[0u8;1024];
    for v in [0.15f32*100.0, 0.35*100.0, 0.65*100.0, 671089.0, 1e30] {
        for p in [0i32, 6, 12, 20] {
            let c=g(v,p,&mut buf); let r=format!("{:.*}",p as usize,v);
            println!("  v={:e} prec={:<2} C++=[{}] Rust=[{}] {}", v,p,c,r, if c==r {"SAME"} else {"DIFFER"});
        }
    }
}
